package nl.slimov.app;
import android.app.*;import android.content.*;
public final class Notice {
 public static Notification build(Context c,String channel,String title,String body,boolean ongoing){NotificationManager manager=c.getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel(channel,channel.equals("watch")?"Actieve reis":"Reis- en verstoringsmeldingen",channel.equals("watch")?NotificationManager.IMPORTANCE_LOW:NotificationManager.IMPORTANCE_HIGH));Intent open=new Intent(c,MainActivity.class);PendingIntent pending=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=new Notification.Builder(c,channel).setSmallIcon(android.R.drawable.ic_dialog_map).setContentTitle(title).setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(pending).setOngoing(ongoing).setOnlyAlertOnce(ongoing).setAutoCancel(!ongoing);if(ongoing){Intent stop=new Intent(c,WatchService.class).setAction("stop");b.addAction(new Notification.Action.Builder(null,"Bewaking stoppen",PendingIntent.getService(c,1,stop,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).build());}return b.build();}
 public static void send(Context c,int id,String title,String body){NotificationManager manager=c.getSystemService(NotificationManager.class);if(manager.areNotificationsEnabled())try{manager.notify(id,build(c,"journey",title,body,false));}catch(SecurityException ignored){}}
}
